from fractions import Fraction
from typing import List, Optional, Tuple

Piece = Tuple[Optional[Fraction], Optional[Fraction], Fraction, Fraction]
# (lo, hi, slope, intercept); None denotes an infinite endpoint


def enumerate_fibre(pieces: List[Piece],
                    breakpoints: List[Fraction],
                    values: List[Fraction],
                    y: Fraction) -> List[Fraction]:
    """All solutions of f(t) = y for a continuous piecewise-affine f.

    `pieces` lists the open affine pieces of f; `breakpoints` and `values`
    record the finitely many junction points and the values there.  Exact
    rational arithmetic, so the returned count is the sheet number sh_f(y).
    """
    solutions: List[Fraction] = []
    for lo, hi, slope, intercept in pieces:
        if slope == 0:
            continue                      # a constant piece is not a local homeo
        t = (y - intercept) / slope
        if (lo is None or t > lo) and (hi is None or t < hi):
            solutions.append(t)
    for b, v in zip(breakpoints, values):
        if v == y:
            solutions.append(b)
    return sorted(set(solutions))


def sheet_number(pieces: List[Piece], breakpoints: List[Fraction],
                 values: List[Fraction], y: Fraction) -> int:
    """sh_f(y) = #f^{-1}(y)."""
    return len(enumerate_fibre(pieces, breakpoints, values, y))

